// AGENTS.md requirement 8: a DSpark sidecar is trained for 4096 positions, so its draft context and
// private window are capped at 4096 positions per parallel slot, however the spec type was chosen
// (`--spec-type draft-dflash` also runs DSpark sidecars) and whether the KV cache is unified.
//
// The test writes a tiny random-weight sidecar in the legacy Prism `dspark` layout (the same tensor set
// as the published Bonsai sidecar, with a Markov head) whose width matches the tiny target generated by
// test-generate-speculative-target, then goes through the real draft-context and driver setup on CPU.

#include "common.h"
#include "speculative.h"

#include "gguf.h"
#include "ggml.h"
#include "llama.h"

#include <chrono>
#include <cstdio>
#include <cstdlib>
#include <filesystem>
#include <random>
#include <string>
#include <vector>

static constexpr int N_EMBD    = 256; // must match the generated target (llama-dense.gguf)
static constexpr int N_VOCAB   = 128; // must match the generated target
static constexpr int N_LAYER   = 2;
static constexpr int N_HEAD    = 4;
static constexpr int N_HEAD_KV = 2;
static constexpr int HEAD_DIM  = N_EMBD / N_HEAD;
static constexpr int N_FF      = 256;
static constexpr int RANK      = 8;

static std::string write_sidecar() {
    const auto stamp = std::chrono::steady_clock::now().time_since_epoch().count();
    const auto path  = std::filesystem::temp_directory_path() / ("test-dspark-draft-cap-" + std::to_string(stamp) + ".gguf");

    gguf_context * g = gguf_init_empty();
    gguf_set_val_str (g, "general.architecture", "dspark");
    gguf_set_val_u32 (g, "dspark.block_count", N_LAYER);
    gguf_set_val_u32 (g, "dspark.context_length", 4096);
    gguf_set_val_u32 (g, "dspark.embedding_length", N_EMBD);
    gguf_set_val_u32 (g, "dspark.feed_forward_length", N_FF);
    gguf_set_val_u32 (g, "dspark.attention.head_count", N_HEAD);
    gguf_set_val_u32 (g, "dspark.attention.head_count_kv", N_HEAD_KV);
    gguf_set_val_u32 (g, "dspark.attention.key_length", HEAD_DIM);
    gguf_set_val_u32 (g, "dspark.attention.value_length", HEAD_DIM);
    gguf_set_val_f32 (g, "dspark.rope.freq_base", 10000.0f);
    gguf_set_val_f32 (g, "dspark.attention.layer_norm_rms_epsilon", 1e-6f);
    gguf_set_val_u32 (g, "dspark.vocab_size", N_VOCAB);
    gguf_set_val_u32 (g, "dspark.dspark.block_size", 4);
    gguf_set_val_u32 (g, "dspark.dspark.mask_token_id", N_VOCAB - 1);
    gguf_set_val_u32 (g, "dspark.dspark.markov_rank", RANK);
    const int32_t target_layers[] = { 0, 1 };
    gguf_set_arr_data(g, "dspark.dspark.target_layers", GGUF_TYPE_INT32, target_layers, 2);
    gguf_set_val_str (g, "tokenizer.ggml.model", "none");

    ggml_init_params ip = { 64ull*1024*1024, nullptr, false };
    ggml_context * ctx = ggml_init(ip);
    std::mt19937 rng(42);
    std::uniform_real_distribution<float> dist(-0.05f, 0.05f);
    auto add = [&](const char * name, int64_t ne0, int64_t ne1, bool ones) {
        ggml_tensor * t = ne1 > 0 ? ggml_new_tensor_2d(ctx, GGML_TYPE_F32, ne0, ne1) : ggml_new_tensor_1d(ctx, GGML_TYPE_F32, ne0);
        ggml_set_name(t, name);
        float * d = (float *) t->data;
        for (int64_t i = 0; i < ggml_nelements(t); ++i) {
            d[i] = ones ? 1.0f : dist(rng);
        }
        gguf_add_tensor(g, t);
    };
    add("token_embd.weight",           N_EMBD, N_VOCAB, false);
    add("dspark.fc.weight",            2*N_EMBD, N_EMBD, false);
    add("dspark.hidden_norm.weight",   N_EMBD, 0, true);
    add("dspark.markov_head_a.weight", RANK, N_VOCAB, false);
    add("dspark.markov_head_b.weight", RANK, N_VOCAB, false);
    add("output_norm.weight",          N_EMBD, 0, true);
    add("output.weight",               N_EMBD, N_VOCAB, false);
    for (int il = 0; il < N_LAYER; ++il) {
        const std::string p = "blk." + std::to_string(il) + ".";
        add((p + "attn_norm.weight").c_str(),   N_EMBD, 0, true);
        add((p + "attn_q.weight").c_str(),      N_EMBD, HEAD_DIM*N_HEAD, false);
        add((p + "attn_k.weight").c_str(),      N_EMBD, HEAD_DIM*N_HEAD_KV, false);
        add((p + "attn_v.weight").c_str(),      N_EMBD, HEAD_DIM*N_HEAD_KV, false);
        add((p + "attn_output.weight").c_str(), HEAD_DIM*N_HEAD, N_EMBD, false);
        add((p + "attn_q_norm.weight").c_str(), HEAD_DIM, 0, true);
        add((p + "attn_k_norm.weight").c_str(), HEAD_DIM, 0, true);
        add((p + "ffn_norm.weight").c_str(),    N_EMBD, 0, true);
        add((p + "ffn_gate.weight").c_str(),    N_EMBD, N_FF, false);
        add((p + "ffn_up.weight").c_str(),      N_EMBD, N_FF, false);
        add((p + "ffn_down.weight").c_str(),    N_FF, N_EMBD, false);
    }
    const bool ok = gguf_write_to_file(g, path.string().c_str(), false);
    gguf_free(g);
    ggml_free(ctx);
    if (!ok) {
        throw std::runtime_error("failed to write the sidecar");
    }
    return path.string();
}

// one configuration: n_parallel slots, unified or per-slot KV, the DSpark sidecar launched as draft-dflash
static bool run_case(llama_model * model_tgt, const std::string & target, const std::string & sidecar, int n_parallel, bool unified) {
    common_params params;
    params.model.path  = target;
    params.n_ctx       = 16384;
    params.n_batch     = 512;
    params.n_ubatch    = 512;
    params.n_parallel  = n_parallel;
    params.kv_unified  = unified;
    params.n_gpu_layers = 0;
    params.speculative.types = { COMMON_SPECULATIVE_TYPE_DRAFT_DFLASH };
    params.speculative.draft.mparams.path = sidecar;
    params.speculative.draft.n_gpu_layers = 0;

    llama_context * ctx_tgt = llama_init_from_model(model_tgt, common_context_params_to_llama(params));
    if (ctx_tgt == nullptr) {
        fprintf(stderr, "failed to create the target context\n");
        return false;
    }

    common_params params_dft = common_base_params_to_speculative(params);
    auto init = common_speculative_init_from_params(params_dft, model_tgt, ctx_tgt);
    llama_context * ctx_dft = init->context();
    if (ctx_dft == nullptr) {
        fprintf(stderr, "failed to create the draft context\n");
        llama_free(ctx_tgt);
        return false;
    }

    params.speculative.draft.ctx_tgt = ctx_tgt;
    params.speculative.draft.ctx_dft = ctx_dft;
    common_speculative * spec = common_speculative_init(params.speculative, n_parallel);
    const llama_pos window = common_speculative_draft_window_capacity(spec);

    const uint32_t n_ctx_dft = llama_n_ctx(ctx_dft);
    const uint32_t cap       = 4096u * (uint32_t) n_parallel;
    const bool ok = n_ctx_dft <= cap && window == 4096;
    printf("n_parallel=%d unified=%d: draft n_ctx=%u (cap %u), window=%d -> %s\n",
            n_parallel, (int) unified, n_ctx_dft, cap, (int) window, ok ? "OK" : "FAIL");

    common_speculative_free(spec);
    init.reset();
    llama_free(ctx_tgt);
    return ok;
}

int main(int argc, char ** argv) {
    if (argc < 2) {
        fprintf(stderr, "usage: %s <target.gguf>\n", argv[0]);
        return 1;
    }
    const std::string target = argv[1];

    llama_backend_init();
    llama_log_set([](ggml_log_level level, const char * text, void *) {
        if (level >= GGML_LOG_LEVEL_WARN) {
            fputs(text, stderr);
        }
    }, nullptr);

    const std::string sidecar = write_sidecar();

    llama_model_params mparams = llama_model_default_params();
    mparams.n_gpu_layers = 0;
    llama_model * model_tgt = llama_model_load_from_file(target.c_str(), mparams);
    if (model_tgt == nullptr) {
        fprintf(stderr, "failed to load the target '%s'\n", target.c_str());
        std::filesystem::remove(sidecar);
        return 1;
    }

    bool ok = true;
    ok &= run_case(model_tgt, target, sidecar, 1, false); // --parallel 1
    ok &= run_case(model_tgt, target, sidecar, 4, true);  // default server: 4 slots, unified KV

    llama_model_free(model_tgt);
    std::filesystem::remove(sidecar);
    llama_backend_free();

    printf("%s\n", ok ? "PASS" : "FAIL");
    return ok ? 0 : 1;
}
